 "content": "def transform(grid):
    # Find connected components under 8-neighbor adjacency for each non-background
    # color. Any component of size 1 is changed to 0, following the demo's
    # isolated 1-pixel object behavior.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for y in range(h):
        for x in range(w):
            c = grid[y][x]
            if c == 3 or (y, x) in seen:
                continue
            stack = [(y, x)]
            seen.add((y, x))
            comp = []
            while stack:
                yy, xx = stack.pop()
                comp.append((yy, xx))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = yy + dy, xx + dx
                        if (dy or dx) and 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == c and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            if len(comp) == 1:
                yy, xx = comp[0]
                out[yy][xx] = 0
    return out
