    for y in range(h):
        for x in range(w):
            c = grid[y][x]
            if c in (0, 3, 4) or (y, x) in seen:
                continue
            stack = [(y, x)]
            seen.add((y, x))
            comp = []
            while stack:
                yy, xx = stack.pop()
                comp.append((yy, xx))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = yy+dy, xx+dx
                        if (dy or dx) and 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == c and (ny,nx) not in seen:
                            seen.add((ny,nx)); stack.append((ny,nx))
            comps.append((len(comp), c, comp))
    if comps:
        _, _, comp = max(comps, key=lambda z:z[0])
        out=[r[:] for r in grid]
        for y,x in comp: out[y][x]=0
        return out
    return [r[:] for r in grid]
